<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --pink: #f2a7a7;
    --mint: #a8d8b9;
    --blue: #8ab4d4;
    --purple: #b5a8d4;
    --yellow: #f9e08b;
    --dark: #2d2d2d;
    --white: #ffffff;
    --grid-color: #c8d8e8;
  }

  body {
    font-family: 'Nunito', sans-serif;
    background-color: #f0f6fb;
    background-image:
      linear-gradient(rgba(200,216,232,0.4) 1px, transparent 1px),
      linear-gradient(90deg, rgba(200,216,232,0.4) 1px, transparent 1px);
    background-size: 32px 32px;
    color: var(--dark);
    padding: 24px 16px 40px;
    max-width: 860px;
    margin: 0 auto;
  }

  /* ── DECORATIVE BLOBS ── */
  .blobs {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    pointer-events: none; z-index: 0; overflow: hidden;
  }
  .blob {
    position: absolute; border-radius: 50%;
    opacity: 0.18;
  }
  .blob-1 { width: 220px; height: 180px; background: var(--pink);   top: -60px; left: -60px; }
  .blob-2 { width: 160px; height: 140px; background: var(--mint);   top: 10px;  right: -40px; border-radius: 60% 40% 70% 30% / 50% 60% 40% 50%; }
  .blob-3 { width: 200px; height: 160px; background: var(--blue);   bottom: 80px; left: -50px; }
  .blob-4 { width: 140px; height: 120px; background: var(--purple); bottom: 20px; right: -30px; }

  /* ── DOTS DECORATION ── */
  .dots {
    display: flex; gap: 4px; margin-bottom: 6px;
  }
  .dots span {
    width: 6px; height: 6px; border-radius: 50%; background: var(--dark); display: inline-block;
  }

  /* ── HERO SECTION ── */
  .hero {
    position: relative; z-index: 1;
    background: white;
    border: 3px solid var(--dark);
    border-radius: 20px;
    padding: 28px 28px 20px;
    margin-bottom: 20px;
    box-shadow: 6px 6px 0 var(--dark);
    display: flex;
    align-items: center;
    gap: 24px;
    flex-wrap: wrap;
  }

  .hero-text { flex: 1; min-width: 220px; }

  .hero-title {
    font-family: 'Baloo 2', cursive;
    font-size: 2.2rem;
    line-height: 1.1;
    color: var(--blue);
    text-shadow: 2px 2px 0 var(--dark);
    margin-bottom: 10px;
  }

  .hero-subtitle {
    display: inline-block;
    background: var(--dark);
    color: white;
    font-family: 'Baloo 2', cursive;
    font-size: 1rem;
    padding: 4px 14px;
    border-radius: 30px;
    letter-spacing: 1px;
    margin-bottom: 14px;
  }

  .hero-desc {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #444;
  }

  /* BEX robot SVG area */
  .bex-wrap {
    position: relative;
    flex-shrink: 0;
  }

  .bex-bubble {
    position: absolute;
    top: -10px; right: -10px;
    background: white;
    border: 2.5px solid var(--dark);
    border-radius: 50% 50% 50% 0;
    padding: 8px 12px;
    font-family: 'Baloo 2', cursive;
    font-size: 0.85rem;
    color: var(--blue);
    font-weight: 800;
    box-shadow: 2px 2px 0 var(--dark);
    white-space: nowrap;
  }

  .bex-img {
    width: 130px;
    height: 130px;
    object-fit: contain;
    filter: drop-shadow(3px 3px 0 rgba(0,0,0,0.15));
  }

  .bex-placeholder {
    width: 130px; height: 130px;
    background: linear-gradient(135deg, #b5e8f5, #8ab4d4);
    border: 3px solid var(--dark);
    border-radius: 50% 50% 45% 45%;
    display: flex; align-items: center; justify-content: center;
    font-size: 3.5rem;
    box-shadow: 4px 4px 0 var(--dark);
  }

  /* ── INFO CARDS ── */
  .cards-grid {
    position: relative; z-index: 1;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 20px;
  }

  .card {
    background: white;
    border: 2.5px solid var(--dark);
    border-radius: 16px;
    padding: 18px 16px;
    box-shadow: 4px 4px 0 var(--dark);
    transition: transform 0.15s;
  }
  .card:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--dark); }

  .card-number {
    font-family: 'Baloo 2', cursive;
    font-size: 2rem;
    font-weight: 800;
    line-height: 1;
    margin-bottom: 6px;
  }
  .card-label {
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #666;
    margin-bottom: 6px;
  }
  .card-value {
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--dark);
    line-height: 1.3;
  }
  .card-list {
    list-style: none;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--dark);
    line-height: 1.8;
  }
  .card-list li::before { content: "• "; font-weight: 900; }

  .card-1 { background: #e8f4fd; }
  .card-1 .card-number { color: var(--blue); }
  .card-2 { background: #fde8e8; }
  .card-2 .card-number { color: var(--pink); }
  .card-3 { background: #e8f7ed; }
  .card-3 .card-number { color: #5aba7d; }
  .card-4 { background: #f3f0fa; }
  .card-4 .card-number { color: var(--purple); }

  /* ── SECTION BOXES ── */
  .section-box {
    position: relative; z-index: 1;
    background: white;
    border: 2.5px solid var(--dark);
    border-radius: 16px;
    padding: 22px 24px;
    margin-bottom: 16px;
    box-shadow: 4px 4px 0 var(--dark);
  }

  .section-title {
    display: inline-block;
    font-family: 'Baloo 2', cursive;
    font-size: 1.1rem;
    font-weight: 800;
    color: white;
    padding: 4px 18px;
    border-radius: 30px;
    border: 2px solid var(--dark);
    margin-bottom: 14px;
    box-shadow: 2px 2px 0 var(--dark);
  }

  .title-pink   { background: var(--pink); color: var(--dark); }
  .title-mint   { background: var(--mint); color: var(--dark); }
  .title-blue   { background: var(--blue); color: white; }
  .title-purple { background: var(--purple); color: white; }

  .section-box p {
    font-size: 0.95rem;
    line-height: 1.7;
    color: #333;
    margin-bottom: 10px;
  }
  .section-box p:last-child { margin-bottom: 0; }

  /* highlight */
  .highlight {
    background: var(--yellow);
    border-left: 4px solid var(--dark);
    padding: 10px 14px;
    border-radius: 0 10px 10px 0;
    font-weight: 700;
    font-size: 0.9rem;
    margin-top: 10px;
  }

  /* ── FINAL TASK BANNER ── */
  .final-task {
    position: relative; z-index: 1;
    background: var(--dark);
    color: white;
    border-radius: 16px;
    padding: 24px 26px;
    margin-bottom: 20px;
    border: 2.5px solid var(--dark);
    box-shadow: 4px 4px 0 var(--pink);
  }

  .final-task .ft-label {
    font-family: 'Baloo 2', cursive;
    font-size: 0.8rem;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--yellow);
    margin-bottom: 6px;
  }

  .final-task h2 {
    font-family: 'Baloo 2', cursive;
    font-size: 1.6rem;
    color: var(--mint);
    margin-bottom: 14px;
  }

  .final-task p {
    font-size: 0.93rem;
    line-height: 1.7;
    color: #ddd;
    margin-bottom: 8px;
  }

  .steps {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 14px;
  }

  .step {
    background: rgba(255,255,255,0.1);
    border: 1.5px solid rgba(255,255,255,0.3);
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 0.85rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    gap: 8px;
    flex: 1;
    min-width: 160px;
  }

  .step-icon {
    font-size: 1.4rem;
    flex-shrink: 0;
  }

  /* ── REFLECTION ── */
  .reflection {
    position: relative; z-index: 1;
    background: #fffbea;
    border: 2.5px dashed var(--dark);
    border-radius: 16px;
    padding: 20px 24px;
    margin-bottom: 20px;
  }

  .reflection p {
    font-size: 0.9rem;
    line-height: 1.7;
    color: #444;
    margin-bottom: 8px;
  }
  .reflection p:last-child { margin-bottom: 0; }

  /* ── FOOTER DOTS ── */
  .footer-dots {
    position: relative; z-index: 1;
    display: flex; justify-content: center; gap: 6px; margin-top: 10px;
  }
  .footer-dots span {
    width: 8px; height: 8px; border-radius: 50%;
    background: var(--dark); display: inline-block;
  }
  .footer-dots span:nth-child(3n+1) { background: var(--pink); }
  .footer-dots span:nth-child(3n+2) { background: var(--mint); }
  .footer-dots span:nth-child(3n)   { background: var(--blue); }

  @media (max-width: 500px) {
    .hero { flex-direction: column; align-items: center; text-align: center; }
    .hero-title { font-size: 1.7rem; }
  }
</style>
